{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "JSA & JHA Builder Online K3 Indonesia",
  "url": "https://wahanatotalita.com/tools/jsa-builder/",
  "description": "Generator dokumen Job Safety Analysis (JSA) dan Job Hazard Analysis (JHA) standar SMK3 PP 50/2012 dan ISO 45001 dengan fitur cetak formulir resmi.",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "All",
  "offers": { "@type": "Offer", "price": "0", "priceCurrency": "IDR" }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Apa perbedaan antara JSA (Job Safety Analysis) dan HIRADC / IBPR?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "HIRADC / IBPR adalah identifikasi bahaya dan penilaian risiko makro yang mencakup seluruh aktivitas, fasilitas, dan proses operasional perusahaan secara menyeluruh. Sedangkan JSA (Job Safety Analysis) bersifat mikro dan taktis, berfokus menganalisis langkah demi langkah dari satu pekerjaan spesifik, terutama pekerjaan berisiko tinggi atau non-rutin sebelum izin kerja (PTW) diterbitkan."
      }
    },
    {
      "@type": "Question",
      "name": "Siapa yang wajib menyusun dan menyetujui dokumen JSA di lapangan?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "JSA idealnya disusun oleh pengawas langsung atau supervisor pekerjaan bersama tim pekerja pelaksana yang memahami teknis lapangan, lalu ditinjau dan divalidasi oleh Petugas / Ahli K3 Umum (HSE Officer), serta disahkan oleh Pimpinan Proyek atau Site Manager sebelum pekerjaan dimulai."
      }
    },
    {
      "@type": "Question",
      "name": "Kapan suatu pekerjaan wajib dilengkapi dokumen JSA?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Dokumen JSA wajib dibuat untuk pekerjaan yang memiliki potensi risiko tinggi (seperti bekerja di ketinggian, ruang terbatas, pekerjaan panas, pengangkatan crane, penggalian dalam), pekerjaan non-rutin yang belum memiliki SOP baku, atau pekerjaan baru dengan perubahan metode/alat kerja."
      }
    }
  ]
}

inline_styles:
:root {
  --navy-dark: #071524;
  --navy: #0D233A;
  --navy-light: #183654;
  --orange: #E8611A;
  --orange-hover: #cf5213;
  --orange-light: #fff2ea;
  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-600: #475569;
  --slate-700: #334155;
  --slate-900: #0F172A;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(13,35,58,0.06);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  background: var(--slate-50);
  color: var(--slate-900);
  line-height: 1.6;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* HERO */
.jsa-hero {
  background: linear-gradient(135deg, #071524 0%, #0D233A 60%, #183654 100%);
  color: #fff;
  padding: 58px 0 44px;
  position: relative;
  overflow: hidden;
  border-bottom: 3px solid var(--orange);
}
.jsa-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 97, 26, 0.18);
  border: 1px solid rgba(232, 97, 26, 0.4);
  padding: 6px 14px;
  border-radius: 999px;
  color: #FFA573;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.jsa-hero h1 {
  font-family: 'Lexend', sans-serif;
  font-size: clamp(1.8rem, 3.6vw, 2.7rem);
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 12px;
}
.jsa-hero h1 span { color: var(--orange); }
.jsa-hero p {
  color: #CBD5E1;
  font-size: 1.05rem;
  max-width: 760px;
  margin-bottom: 20px;
}
.hero-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-tag {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  color: #E2E8F0;
}

/* JSA WORKSPACE */
.jsa-wrapper { padding: 40px 0 60px; }
.card-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  padding: 28px;
  margin-bottom: 28px;
}
.card-header-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--slate-100);
  padding-bottom: 16px;
  margin-bottom: 22px;
  flex-wrap: wrap;
  gap: 12px;
}
.card-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 10px;
}

/* TEMPLATES PRESET */
.preset-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}
.preset-btn {
  background: var(--slate-100);
  border: 1px solid var(--slate-200);
  padding: 8px 14px;
  border-radius: 8px;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--slate-700);
  cursor: pointer;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.preset-btn:hover, .preset-btn.active {
  background: var(--navy);
  border-color: var(--navy);
  color: #fff;
}

/* HEADER METADATA FORM */
.meta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  background: var(--slate-50);
  padding: 18px;
  border-radius: var(--radius-md);
  border: 1px solid var(--slate-200);
  margin-bottom: 26px;
}
.form-field { margin-bottom: 0; }
.form-label {
  display: block;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.form-input {
  width: 100%;
  padding: 9px 12px;
  border: 1.5px solid var(--slate-200);
  border-radius: 8px;
  font-size: 0.9rem;
  color: var(--slate-900);
  background: #fff;
}
.form-input:focus {
  outline: none;
  border-color: var(--orange);
}

/* JSA STEPS TABLE */
.jsa-table-container {
  overflow-x: auto;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 22px;
}
.jsa-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 860px;
  font-size: 0.88rem;
}
.jsa-table th {
  background: var(--navy);
  color: #fff;
  padding: 12px 14px;
  text-align: left;
  font-weight: 700;
  font-size: 0.84rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.jsa-table td {
  padding: 12px 14px;
  border-bottom: 1px solid var(--slate-200);
  vertical-align: top;
  background: #fff;
}
.jsa-table tr:hover td { background: var(--slate-50); }
.jsa-table textarea {
  width: 100%;
  border: 1px solid var(--slate-200);
  border-radius: 6px;
  padding: 8px 10px;
  font-size: 0.86rem;
  font-family: inherit;
  resize: vertical;
  min-height: 64px;
}
.jsa-table textarea:focus {
  outline: none;
  border-color: var(--orange);
}
.risk-select {
  padding: 6px 10px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 0.8rem;
  border: 1px solid var(--slate-300);
}
.risk-low { background: #DCFCE7; color: #166534; }
.risk-med { background: #FEF3C7; color: #92400E; }
.risk-high { background: #FEE2E2; color: #991B1B; }

.btn-del-step {
  background: #FEE2E2;
  border: 1px solid #FCA5A5;
  color: #991B1B;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
}
.btn-del-step:hover { background: #EF4444; color: #fff; }

/* ACTIONS */
.action-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.btn-add-step {
  background: var(--navy-light);
  color: #fff;
  border: none;
  padding: 10px 18px;
  border-radius: 8px;
  font-size: 0.88rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.btn-add-step:hover { background: var(--navy); }

.export-group { display: flex; gap: 10px; }
.btn-export {
  padding: 10px 18px;
  border-radius: 8px;
  font-size: 0.88rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: none;
  text-decoration: none;
}
.btn-print { background: var(--orange); color: #fff; }
.btn-print:hover { background: var(--orange-hover); }
.btn-csv { background: var(--slate-100); color: var(--navy); border: 1.5px solid var(--slate-300); }
.btn-csv:hover { background: var(--slate-200); }

/* EDITORIAL ARTICLE */
.editorial-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  margin-bottom: 32px;
}
.editorial-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  border-left: 4px solid var(--orange);
  padding-left: 14px;
}
.editorial-p {
  color: var(--slate-700);
  font-size: 0.96rem;
  line-height: 1.7;
  margin-bottom: 16px;
}

/* FAQ */
.faq-item {
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
}
.faq-q {
  width: 100%;
  padding: 16px 20px;
  text-align: left;
  background: #fff;
  border: none;
  font-family: 'Lexend', sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-q:hover { background: var(--slate-50); }
.faq-a {
  padding: 0 20px 18px;
  color: var(--slate-700);
  font-size: 0.92rem;
  line-height: 1.65;
  display: none;
}
.faq-item.active .faq-a { display: block; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.2s; }

